corrected_code:
class TopSecretDossierDownloadView(View):
    def get(self, request, dossier_uuid):
        dossier = get_object_or_404(ClassifiedDossier, uuid=dossier_uuid)
        if not request.user.has_perm('dossiers.view_classifieddossier', dossier):
            raise PermissionDenied("Insufficient security clearance.")
        return FileResponse(dossier.encrypted_archive.open('rb'), content_type='application/octet-stream')
